CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL CHECK(username=lower(username)), salt TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','admin')), created_at DOUBLE PRECISION NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at DOUBLE PRECISION NOT NULL,expires_at DOUBLE PRECISION NOT NULL);
CREATE TABLE csrf(token_hash TEXT PRIMARY KEY,session_hash TEXT REFERENCES sessions(token_hash) ON DELETE CASCADE,expires_at DOUBLE PRECISION NOT NULL);
CREATE TABLE guards(account_key TEXT PRIMARY KEY,failures INTEGER NOT NULL DEFAULT 0,locked_until DOUBLE PRECISION NOT NULL DEFAULT 0,updated_at DOUBLE PRECISION NOT NULL);
CREATE TABLE rate_hits(id BIGSERIAL PRIMARY KEY,bucket TEXT NOT NULL,at DOUBLE PRECISION NOT NULL);
CREATE INDEX rate_bucket_at ON rate_hits(bucket,at);
CREATE TABLE audit(id TEXT PRIMARY KEY,sequence BIGSERIAL UNIQUE NOT NULL,timestamp DOUBLE PRECISION NOT NULL,username TEXT NOT NULL,account_id TEXT,ip TEXT NOT NULL,user_agent TEXT NOT NULL,outcome TEXT NOT NULL,status INTEGER NOT NULL,duration_ms DOUBLE PRECISION NOT NULL,controls TEXT NOT NULL);
CREATE INDEX audit_time ON audit(timestamp);
CREATE INDEX audit_outcome ON audit(outcome);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),policy TEXT NOT NULL);
